  const pixelID = '<YOUR_PIXEL_ID>';

  // Fügen Sie einen Ereignis-Zuhörer zum Rückruf-Button hinzu
  document.querySelector('#callback-button').addEventListener('click', function() {

    // Senden Sie das Facebook-Custom-Conversion-Ereignis
