      'fb_custom_param': 'custom_value'
    });

  });

  // Facebook-Pixel-Skript laden
  (function(f, b, e, v, n, t, s) {
    if (f.fbq) return;
    n = f.fbq = function() {
      n.callMethod ? n.callMethod.apply(n, arguments) : n.queue.push(arguments)
    };
    if (!f._fbq) f._fbq = n;
    n.push = n;
    n.loaded = !0;
    n.version = '2.0';
    n.queue = [];
    t = b.createElement(e);
    t.async = !0;
    t.src = v;
    s = b.getElementsByTagName(e)[0];
    s.parentNode.insertBefore(t, s)
  })(window, document, 'script', 'https://connect.facebook.net/en_US/fbevents.js');

  // Facebook-Pixel mit Ihrer Pixel-ID initialisieren
  fbq('init', pixelID);

</script>
```

Hier ist eine Aufschlüsselung dessen, was der Code tut:
* Zuerst definieren wir die Facebook-Pixel-ID, indem wir `<YOUR_PIXEL_ID>` durch die tatsächliche Pixel-ID ersetzen.
* Dann fügen wir mit `document.querySelector()` einen Ereignis-Zuhörer zum Rückruf-Button hinzu. Das `click` Ereignis löst das benutzerdefinierte Conversion-Ereignis aus.
* Innerhalb des Ereignis-Zuhörers verwenden wir die `fbq()` Funktion, um das Facebook Custom Conversion Ereignis zu senden. Ersetzen Sie `<YOUR_EVENT_NAME>` durch den tatsächlichen Namen Ihres benutzerdefinierten Ereignisses. Sie können auch benutzerdefinierte Parameter hinzufügen, indem Sie `custom_value` durch den tatsächlichen Wert ersetzen, den Sie übergeben möchten.
* Als Nächstes laden wir das Facebook-Pixel-Skript mithilfe des von Facebook bereitgestellten Codes. Dies lädt die `fbevents.js` Bibliothek.
* Schließlich initialisieren wir das Facebook-Pixel, indem wir `fbq('init', pixelID)` mit Ihrer Pixel-ID als Argument aufrufen.

Hinweis: Dieser Code setzt voraus, dass Sie das Facebook-Pixel bereits in Ihrer Website eingerichtet und den Basiscodesatz zu Ihrem Google Tag Manager-Container hinzugefügt haben. Sie müssen auch den `#callback-button` Selektor durch den tatsächlichen Selektor für Ihren Rückruf-Button ersetzen.

