Hier ist ein einfaches C-Programm, das Zahlen aus einer Datei liest und die zweitgrößte Zahl im Array findet:

```
#include <stdio.h>
#include <stdlib.h>
int main() {
  FILE *fp;
  int num, max1, max2;

  // Öffnen Sie die Datei zum Lesen
  fp = fopen("numbers.txt", "r");

  // Lesen Sie die erste Zahl aus der Datei
  fscanf(fp, "%d",&num);

  // Initialisieren Sie max1 und max2 mit der ersten Zahl
  max1 = num;
  max2 = num;

  // Lesen Sie den Rest der Zahlen aus der Datei
  while (fscanf(fp, "%d",&num) == 1) {
    // Wenn die aktuelle Zahl größer ist als max1, aktualisieren Sie max1 und max2
    if (num > max1) {
      max2 = max1;
      max1 = num;
    }
    // Wenn die aktuelle Zahl größer als max2, aber kleiner als max1 ist, aktualisieren Sie max2
    else if (num > max2) {
      max2 = num;
    }
  }

  // Schließen Sie die Datei
  fclose(fp);

  // Geben Sie die zweitgrößte Zahl aus
  printf("Die zweitgrößte Zahl ist: %d\n", max2);

  return 0;
}
```

