```javascript
// Alle DOM-Elemente mit der Klasse "jetAction" oder "jetLabel" erhalten
const elements = document.querySelectorAll('.jetAction, .jetLabel');
// Schleife durch jedes Element
elements.forEach(element => {
  // Die innerHTML des Elements erhalten
  let html = element.innerHTML;

  // Verwenden Sie einen regulären Ausdruck, um alle Instanzen von {{ Variable }} zu finden
  const regex = /{{\s*(.*?)\s*}}/g;
  let match;

  // Durchlaufen Sie jedes vom Regex gefundene Übereinstimmung
  while (match = regex.exec(html)) {
    // Den Variablennamen aus der Übereinstimmung erhalten
    const variable = match[1];

    // Überprüfen Sie, ob die Variable im Pläne-Objekt vorhanden ist
    if (variable in plans) {
      // Ersetzen Sie die Variable durch ihren Wert im Pläne-Objekt
      html = html.replace(match[0], plans[variable].price);
