```typescript
function jpr_service_fee(prod_value: number): number {
  const thresholds: number[] = [0, 80, 128, 208, 336, 544, 880];
  const rates: number[] = [0.0990, 0.0690, 0.0480, 0.0340, 0.0240, 0.0170, 0.012];
