Hier ist der fertige Code unter Verwendung einer for-Schleife:
```c
#include <iostream>
using namespace std;
int main()
{
    int num;
    cout << "Geben Sie die Nummer ein: ";
    cin >> num;
    if (num <= 0)
    {
        cout << "Bitte geben Sie eine Zahl größer als 0 ein" << endl;
        return 0;
    }
    // Schleife, bis die Zahl entweder 1 (glücklich) oder 4 (unglücklich) ist
    for (;;)
    {
        int sum = 0;
        while (num > 0)
        {
            int ziffer = num % 10;
            sum += ziffer * ziffer;
            num /= 10;
        }
        if (sum == 1)
        {
