  pinMode (IO_LINE, INPUT_PULLUP);
  // Setzen Sie die LED als Ausgang
  pinMode (LED, OUTPUT);
  // Legen Sie die PWM-Frequenz für den LED-Pin fest
  analogWriteFrequency (LED, 38000);
