Ein beliebtes Go-Bibliothek zum Lesen von Werten aus einer YAML-Datei ist "gopkg.in/yaml.v3". Hier ist ein Beispiel davon, wie Sie es verwenden können:
```
Paket Haupt
import (
    "FMT"
    "io/ioutil"
    "Protokoll"
    "gopkg.in/yaml.v3"
)
Art Config struct {
    Datenbankstruktur {
        Host     string "yaml:"host""
        Port     int    "yaml:"Port""
        Benutzername zeichenfolge "yaml:"Benutzername""
        Passwort zeichenfolge "yaml:"Passwort""
        Name     zeichenfolge "yaml:"name""
    } "yaml:"Datenbank""
}
Funktion Haupt() {
    // YAML-Datei lesen
    Daten, fehler := ioutil.ReadFile("config.yaml")
    Wenn fehler != nil {
        Protokoll.Fatalf("Fehler: %v", fehler)
    }
    // Möchte YAML-Daten in Config-Struktur unmarshallen
    var Konfiguration Config
    err = yaml.Unmarshal(data, &konfiguration)
    Wenn fehler != nil {
        Protokoll.Fatalf("Fehler: %v", fehler)
    }
    // Werte ausgeben
    FMT.Printf("Datenbank-Host: %s\n", konfiguration.Datenbankstruktur.Host)
    FMT.Printf("Datenbank-Port: %d\n", konfiguration.Datenbankstruktur.Port)
