2. Erstellen Sie eine benutzerdefinierte `ListenAndServe`-Funktion, die eine Anycast-IP-Adresse und einen Port akzeptiert:
```go
func ListenAndServeAnycast(addr string, handler http.Handler) error {
    // Lösen Sie die Anycast-IP-Adresse auf
    ip := net.ParseIP(addr)
    if ip == nil {
        return fmt.Errorf("ungültige Anycast-IP-Adresse: %s", addr)
    }
    // Erstellen Sie einen TCP-Listener auf der Anycast-IP-Adresse und dem Port
    tcpAddr := &net.TCPAddr{IP: ip, Port: port}
    listener, err := net.ListenTCP("tcp", tcpAddr)
    if err != nil {
        return err
    }
    // Erstellen Sie einen HTTP-Server mit dem angegebenen Handler
    server := &http.Server{Handler: handler}
    // Starten Sie das Bedienen von Anfragen
    return server.Serve(listener)
}
```
3. Ändern Sie die `main`-Funktion, um die benutzerdefinierte `ListenAndServe`-Funktion zu verwenden:
```go
func main() {
    // Erstellen Sie einen neuen Gin-Router
    r := gin.Default()
    // Definieren Sie hier Ihre Routen
    r.GET("/", func(c *gin.Context) {
        c.String(http.StatusOK, "Hallo Welt!")
    })
    // Starten Sie den HTTP-Server unter Verwendung der Anycast-IP-Adresse und des Ports
    if err := ListenAndServeAnycast("10.0.0.1", r); err != nil {
        log.Fatal(err)
    }
}
```
