```php
<?php
$spaceName = $_GET['spacename'];
$messageText = $_GET['messagetext'];
// Google Chat API URL
$url = "https://chat.googleapis.com/v1/spaces/$spaceName/messages";
// Service account credentials
$serviceAccountEmail = "your_service_account_email_here@your_project_id_here.iam.gserviceaccount.com";
$privateKeyFile = "path/to/your/private/key/file.json";
// Create a JWT token for authentication
$now = time();
$jwt = array(
    "iss" => $serviceAccountEmail,
    "aud" => "https://chat.googleapis.com/",
    "iat" => $now,
    "exp" => $now + 3600,
    "scope" => "https://www.googleapis.com/auth/chat.bot"
);
$jwtHeader = base64_encode(json_encode(array("alg" => "RS256", "typ" => "JWT")));
$jwtPayload = base64_encode(json_encode($jwt));
$jwtSignature = "";
openssl_sign($jwtHeader . "." . $jwtPayload, $jwtSignature, file_get_contents($privateKeyFile), "sha256WithRSAEncryption");
$jwtSignature = base64_encode($jwtSignature);
$jwtToken = $jwtHeader . "." . $jwtPayload . "." . $jwtSignature;
// Create the message payload
$messagePayload = array(
    "text" => $messageText
);
$data = array(
    "text" => $messageText
);
$options = array(
    "http" => array(
