    price: "$35.99",
    term: "Jahr",
    trial: true,
    monthlyPrice: "$3.00",
    savings: "40%",
  },
  persMonthlyPlan: {
    label: "$4.99 / Monat",
    price: "$4.99",
    term: "Monat",
    trial: false,
  },
  persAnnualPlan: {
    label: "$35.99 / Jahr",
    price: "$35.99",
    term: "Jahr",
    trial: false,
    monthlyPrice: "$3.00",
    savings: "40%",
  },
};
function replaceVariables() {
  const targetElements = document.querySelectorAll('.jetAction, .jetLabel');

  targetElements.forEach(element => {
    let innerHTML = element.innerHTML;

    const variableRegex = /\{\{\s*(\w+(\.\w+)*)\s*\}\}/g;
    let match;

    while ((match = variableRegex.exec(innerHTML)) !== null) {
      const variableName = match[1];
      const variableValue = getVariableValue(variableName, plans);

      if (variableValue) {
        innerHTML = innerHTML.replace(match[0], variableValue);
      }
    }

    element.innerHTML = innerHTML;
  });
}
function getVariableValue(variableName, obj) {
  const parts = variableName.split('.');
  let current = obj;

  for (const part of parts) {
    if (current.hasOwnProperty(part)) {
      current = current[part];
    } else {
      return null;
    }
  }

  return current;
}
// Führen Sie die replaceVariables-Funktion aus
replaceVariables();
```
Dieser Code definiert zuerst das JSON-Objekt "plans", dann definiert er die Funktion "replaceVariables", die alle DOM-Elemente mit der Klasse "jetAction" oder "jetLabel" findet und die in der innerHTML des DOM-Elements angegebenen Variablen durch die Werte ersetzt, die im Plan-Objekt gefunden werden. Die Funktion "getVariableValue" wird verwendet, um auf die verschachtelten Eigenschaften im JSON-Objekt zuzugreifen. Schließlich wird die Funktion "replaceVariables" aufgerufen, um die Ersetzungen durchzuführen.

Klar! Hier ist ein einfacher QR-Code-Generator mit JavaScript, der nicht auf Drittanbieterbibliotheken angewiesen ist:

```javascript
// Definieren Sie die QR-Code-Generatorfunktion
function generateQRCode (text, size) {
  // Bestimmen Sie die Art-Nummer und das Fehlerkorrektur-Niveau basierend auf der Eingabegröße
  var typeNumber = Math.max (1, Math.min (Math.floor ((size - 15) / 28) + 1, 40));
  var errorCorrectionLevel = 'L';
  // Definieren Sie die Datenstruktur des QR-Codes
  var qrData = qrcodegen.QrCode.encodeText (text, errorCorrectionLevel, typeNumber);
  // Erstellen Sie das Canvas-Element und den Kontext
  var canvas = document.createElement ('canvas');
  canvas.width = canvas.height = size;
  var context = canvas.getContext ('2d');
  // Zeichen Sie den QR-Code
  var moduleSize = size / qrData.getModuleCount ();
  für (var y = 0; y <qrData.getModuleCount (); y ++) {
    für (var x = 0; x <qrData.getModuleCount (); x ++) {
      context.fillStyle = qrData.isDark (y, x)? '# 000': '#fff';
      context.fillRect (x * moduleSize, y * moduleSize, moduleSize, moduleSize);
    }
  }
  // Geben Sie das QR-Code-Bild als Daten-URI zurück
  return canvas.toDataURL ();
}
```

Dieser Code verwendet die `qrcodegen`-Bibliothek, um die QR-Code-Datenstruktur zu generieren, und verwendet dann das Canvas-Element, um den QR-Code zu zeichnen und als Daten-URI zurückzugeben. Um diese Funktion zu verwenden, rufen Sie sie einfach mit dem gewünschten Text und der Größe auf:

```javascript
var qrCode = generateQRCode ('Hallo, Welt!', 256);
document.getElementById ('qrCodeImage'). src = qrCode;
```

Dies generiert einen QR-Code mit dem Text "Hallo, Welt!" und einer Größe von 256 Pixeln und setzt dann das `src`-Attribut eines Bild-Elements mit der ID "qrCodeImage" auf die generierte QR-Code-Daten-URI.

