Klar! Hier ist ein einfacher Glüheffekt-Shader, den Sie in Unity verwenden können:

```
Shader "Custom/GlowShader"
{
    Properties
    {
        _Color("Color", Color) = (1,1,1,1)
        _GlowColor("Glow Color", Color) = (1,1,1,1)
        _GlowPower("Glow Power", Range(0, 10)) = 1
    }
    SubShader
    {
        Tags
        {
            "RenderType"="Opaque"
        }
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            struct appdata
            {
                float4 vertex : POSITION;
                float4 texcoord : TEXCOORD0;
            };
            struct v2f
            {
                float4 vertex : SV_POSITION;
                float4 texcoord : TEXCOORD0;
            };
            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.texcoord = v.texcoord;
                return o;
            }
            fixed4 frag (v2f i) : SV_Target
            {
                fixed4 col = tex2D(_MainTex, i.texcoord.xy);
                col.rgb += _GlowColor.rgb * pow(col.a, _GlowPower);
                col *= _Color;
                return col;
            }
            ENDCG
        }
    }
}
```

Um diesen Shader zu verwenden, erstellen Sie ein neues Material und wählen Sie den Shader "Custom / GlowShader" aus dem Dropdown-Menü aus. Dann können Sie diesem Material Ihre Prefab zuweisen und die Eigenschaften "Glow Color" und "Glow Power" anpassen, um die Intensität und Farbe des Glüheffekts zu kontrollieren.

