 VAirTransition data
 => data switch
 {
 { Transition: VAirTransition.Type.Start, VAir: 5 } => new Start5Ms(),
 { Transition: VAirTransition.Type.Stop, VAir: 5 } => new Stop5Ms(),
 { Transition: VAirTransition.Type.Start, VAir: 15 } => new Start15Ms(),
