```javascript
import { renderHook } from '@testing-library/react-hooks';
import { useDispatch, useSelector } from 'react-redux';
import { clearAssets } from '../actions';
import useOrderInteractions from './useOrderInteractions';
jest.mock('react-redux');
describe('useOrderInteractions', () => {
