Hier ist etwas Beispiel-C#-Code, um einen String in ein gzip-komprimiertes Byte-Array umzuwandeln:

```
using System;
using System.IO;
using System.IO.Compression;
namespace ConsoleApp
{
    class Program
    {
        static void Main(string[] args)
        {
            // Der String, der komprimiert werden soll
            string text = "This is the string to compress";
            // Konvertieren Sie den String in ein Byte-Array
            byte[] inputBytes = System.Text.Encoding.UTF8.GetBytes(text);
            // Verwenden Sie einen MemoryStream, um die komprimierten Daten zu halten
            using (MemoryStream outputStream = new MemoryStream())
            {
                // Verwenden Sie den GZipStream, um die Daten zu komprimieren
                using (GZipStream gzip = new GZipStream(outputStream, CompressionLevel.Optimal))
                {
                    gzip.Write(inputBytes, 0, inputBytes.Length);
                }
                // Holen Sie sich die komprimierten Daten als Byte-Array
                byte[] compressedBytes = outputStream.ToArray();
            }
        }
    }
}
```
Dieser Code verwendet die `System.IO.Compression.GZipStream`-Klasse, um die Daten im Eingangs-String zu komprimieren, und schreibt dann die komprimierten Daten in einen `MemoryStream`. Die resultierenden komprimierten Daten werden dann in ein Byte-Array konvertiert und in der Variable `compressedBytes` gespeichert.

